sp_widget.client_script:
api.controller = function($scope, spUtil, $window, spContextManager) {
  var c = this;
  c.isRecording = false;
  c.transcript = "";
  c.status = "";

  var SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  var recognition;

  if (SpeechRecognition) {
    recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.onresult = function(event) {
      c.transcript = event.results[0][0].transcript;
      c.isRecording = false;
      $scope.$apply();
    };
  }

  c.toggleListening = function() {
    if (!SpeechRecognition) {
      spUtil.addErrorMessage("Speech recognition not supported in browser. Please type your request below.");
      return;
    }
    if (c.isRecording) {
      recognition.stop();
      c.isRecording = false;
    } else {
      c.transcript = "";
      recognition.start();
      c.isRecording = true;
    }
  };

  c.submitRequest = function() {
    c.status = "Submitting request...";
    c.server.get({
      action: 'create_interaction',
      text: c.transcript
    }).then(function(r) {
      if (r.data.success) {
        c.status = "Request submitted! Interaction Created: " + r.data.sys_id;
        c.transcript = "";
      }
    });
  };

  // --- REDIRECT TO CHAT PAGE ---
  c.openAiChat = function() {

	spContextManager.addContext('agent-chat', {
		hotel_name: c.data.hotelName || "",
		city: c.data.city || "",
		country: c.data.country || "",
		room_id: c.data.roomNumber || "",
		guest_name: c.data.guestName || ""
	});

	};
};

sp_widget.css:
.btn-circle {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  font-size: 32px;
  line-height: 80px;
  padding: 0;
}

.pulse {
  animation: pulse-animation 1.5s infinite;
}

@keyframes pulse-animation {
  0% { box-shadow: 0 0 0 0px rgba(217, 83, 79, 0.7); }
  100% { box-shadow: 0 0 0 20px rgba(217, 83, 79, 0); }
}

.margin-top-10 { 
  margin-top: 10px; 
}

.margin-bottom-20 { 
  margin-bottom: 20px; 
}

sp_widget.script:
(function() {
  options.public = true;

  data.hotelName = $sp.getParameter('hotel_name') || "Grand Hyatt";
  data.country = $sp.getParameter('country') || "USA";
  data.city = $sp.getParameter('city') || "San Diego";
  data.roomNumber = $sp.getParameter('room_id') || "Room 402";
  data.guestName = $sp.getParameter('guest_name') || "Valued Guest";

  if (input && input.action === 'create_interaction') {
    var gr = new GlideRecord('interaction');
    gr.initialize();
    gr.short_description = input.text;

    // Custom field mapping on interaction table
    gr.x_snc_flowops_hotel_name = data.hotelName;
    gr.x_snc_flowops_country = data.country;
    gr.x_snc_flowops_city = data.city;
    gr.x_snc_flowops_room_number = data.roomNumber;
    gr.x_snc_flowops_guest_name = data.guestName; 

    gr.channel = 'walkup_portal';
    var sysId = gr.insert();

    data.success = true;
    data.sys_id = sysId;
  }
})();
